import numpy as np


def l2_norm(v):
    v = np.asarray(v, dtype=float)
    return float(np.sqrt(np.sum(v ** 2)))


def normalize(v):
    v = np.asarray(v, dtype=float)
    length = l2_norm(v)
    if length == 0:
        raise ValueError("the zero vector has no direction")
    return v / length


def distance(a, b):
    return l2_norm(np.asarray(a, dtype=float) - np.asarray(b, dtype=float))

