import numpy as np


def layer(W, b, x):
    W, b, x = np.asarray(W), np.asarray(b), np.asarray(x)
    rows, columns = W.shape
    if columns != x.shape[0]:
        raise ValueError(f"W has {columns} columns but x has size {x.shape[0]}")
    if rows != b.shape[0]:
        raise ValueError(f"W has {rows} rows but b has size {b.shape[0]}")
    return W @ x + b


def param_count(sizes):
    return sum(n_in * n_out + n_out for n_in, n_out in zip(sizes, sizes[1:]))

