import numpy as np


def sigmoid(z):
    return 1 / (1 + np.exp(-z))


def sigmoid_grad(z):
    s = sigmoid(z)
    return s * (1 - s)


def tanh_grad(z):
    return 1 - np.tanh(z) ** 2


def relu_grad(z):
    return (np.asarray(z) > 0).astype(float)


def stacked_sigmoid_slope(z, depth):
    slope = 1.0
    for _ in range(depth):
        slope *= sigmoid_grad(z)
        z = sigmoid(z)
    return float(slope)

