import math
import numpy as np


def _checked(values, probs):
    values = np.asarray(values, dtype=float)
    probs = np.asarray(probs, dtype=float)
    if np.any(probs < 0) or abs(probs.sum() - 1) > 1e-9:
        raise ValueError("probabilities must be non-negative and sum to 1")
    return values, probs


def expectation(values, probs):
    values, probs = _checked(values, probs)
    return float(values @ probs)


def variance(values, probs):
    values, probs = _checked(values, probs)
    mean = values @ probs
    return float(((values - mean) ** 2) @ probs)


def gaussian_nll(y, mu, sigma):
    y = np.asarray(y, dtype=float)
    terms = 0.5 * math.log(2 * math.pi * sigma ** 2) + (y - mu) ** 2 / (2 * sigma ** 2)
    return float(np.mean(terms))

