import numpy as np


def softmax(z):
    z = np.asarray(z, dtype=float)
    e = np.exp(z - z.max())
    return e / e.sum()


def cross_entropy(z, target):
    z = np.asarray(z, dtype=float)
    top = z.max()
    log_sum_exp = top + np.log(np.sum(np.exp(z - top)))
    return float(log_sum_exp - z[target])


def cross_entropy_grad(z, target):
    grad = softmax(z)
    grad[target] -= 1
    return grad

